_PROJECT = re.compile(r'项目|副业|接单|试玩|任务|分成|挂[gG机播]|托管|自动运行|多开|矩阵|一部手机|用手机|手机ai|单机|单窗口|单账号|赛道|小白可做|人人可做|掘金|玩法|免门槛|零门槛|0门槛|零成本|(?:稳定|可持续)增收', re.I)
_PROJECT_PURPOSE = re.compile(r'实拍|实战|案例|教程|教学|揭秘|实操|推广|操作|任务|变现|出单|日收|副业|兼职|稿费|赚[钱美米金\d]|賺[钱美米金\d]|搞钱|收益|收入|创收|增收|月[入获赚]|日[入获赚]|一天.{0,10}(?:赚|賺|收益|一单)')
_READING = re.compile(r'文章|文档|随笔|见闻|心得|经验|复盘|故事|访谈|观点|逻辑|现实认知|人性|建议|避坑|技能|通知|注意事项|观察与思考')
_PACK = re.compile(r'合集|资料包|资源包|课程|训练营|课件|目录|教程|教学|手册|学习|分享|资源|线下课|全流程|提升课|进阶课|全套|详解|精讲|指南|[0-9]{1,3}\s*(?:节|讲|合集)')
_OPERATIONS = re.compile(r'技术|方法|解决|报错|设置|异常|提示.{0,6}处理|版本更新')


def reference_topic(title, received):
    """Group accessible reference entries by what the publisher actually offers."""
    if _SITE_NOTE.search(title):
        return 'reference','站点说明'
    if re.search(r'^(?:(?:某|微信)?公众号)?付费文章\s*[:：]|(?:读书笔记|阅读随笔)', title):
        return 'reference','经验与阅读'
    lead = title + ' ' + received[:220]
    if _PROJECT.search(lead) and (_PROJECT_PURPOSE.search(lead) or '项目群' in title):
        return 'reference','项目线索'
    if _READING.search(title):
        return 'reference','经验与阅读'
    if _PACK.search(title) or re.search(r'^\s*(?:课程|学习)(?:介绍|目录|大纲)', received):
        return 'reference','课程与资料'
    if _OPERATIONS.search(title):
        return 'reference','操作方法'
    return '', ''
